'use strict';

var resolve = require( 'path' ).resolve;
var fromMarkdown = require( '@stdlib/_tools/semantic-document/from-markdown' );
var readFileSync = require( '@stdlib/fs/read-file' ).sync;
var toIPYNB = require( './../lib' );

var opts = {
	'encoding': 'utf8'
};
var markdown = readFileSync( resolve( __dirname, 'fixtures', 'abs.md.txt' ), opts ); // eslint-disable-line n/no-sync

var doc = fromMarkdown( markdown, {
	'profile': 'readme'
});
var notebook = toIPYNB( doc );

console.log( toIPYNB.stringify( notebook ) );
